"use client";

import { FlowDiagram } from "@diax/react";
import {
  Briefcase,
  Code,
  Cpu,
  Database,
  type LucideIcon,
  Paintbrush,
  ShieldCheck,
  User,
} from "lucide-react";

interface ProfileNodeProps {
  icon: LucideIcon;
  jobTitle: string;
  name: string;
  level: "c-suite" | "vp" | "lead";
  active?: boolean;
}

// Beautiful interactive modern SaaS Profile Node
const ProfileNode = ({ icon: Icon, jobTitle, name, level, active }: ProfileNodeProps) => {
  const isCSuite = level === "c-suite";
  const isVP = level === "vp";

  return (
    <div
      className={`group relative flex flex-col items-center justify-center min-w-[200px] px-6 py-6 rounded-[2rem] border bg-black/40 backdrop-blur-xl shadow-2xl transition-all duration-500 hover:-translate-y-2 hover:shadow-[0_20px_40px_-15px_rgba(255,255,255,0.1)] overflow-hidden ${
        isCSuite
          ? "border-amber-500/30 hover:border-amber-500/60"
          : isVP
            ? "border-purple-500/30 hover:border-purple-500/60"
            : "border-white/10 hover:border-white/30"
      }`}
    >
      {/* Decorative inner glow */}
      <div
        className={`absolute top-0 right-0 h-16 w-16 bg-gradient-to-bl blur-[30px] rounded-full pointer-events-none opacity-60 ${
          isCSuite ? "from-amber-400" : isVP ? "from-purple-400" : "from-emerald-400"
        }`}
      ></div>

      {/* Status bead indicator */}
      <div className="absolute top-4 left-4 flex gap-1 items-center">
        <div
          className={`h-1.5 w-1.5 rounded-full ${active ? "bg-emerald-400 shadow-[0_0_8px_#34d399] animate-pulse" : "bg-white/20"}`}
        ></div>
      </div>

      {/* Avatar Container */}
      <div className="relative mb-4 flex h-16 w-16 items-center justify-center rounded-2xl bg-white/5 shadow-inner border border-white/10 group-hover:scale-110 transition-transform duration-500 z-10">
        <Icon
          className={`h-7 w-7 ${
            isCSuite ? "text-amber-400" : isVP ? "text-purple-400" : "text-emerald-400"
          }`}
          strokeWidth={1.5}
        />
      </div>

      <div className="flex flex-col items-center text-center z-10 w-full mb-3">
        <span className="text-sm font-bold tracking-wide text-white">{jobTitle}</span>
        <span className="text-[11px] text-white/50 mt-1 uppercase tracking-[0.2em] font-mono">
          {name}
        </span>
      </div>

      {/* Mini interactive stats bar */}
      <div className="flex items-center gap-3 w-full border-t border-white/10 pt-3 mt-1">
        <div className="flex-1 flex flex-col">
          <span className="text-[9px] text-white/30 uppercase">Reports</span>
          <span className="text-xs text-white/80 font-mono font-medium">
            {isCSuite ? 8 : isVP ? 4 : 12}
          </span>
        </div>
        <div className="h-6 w-[1px] bg-white/10"></div>
        <div className="flex-1 flex flex-col text-right">
          <span className="text-[9px] text-white/30 uppercase">Perf</span>
          <span className="text-xs text-emerald-400 font-mono font-medium">98%</span>
        </div>
      </div>
    </div>
  );
};

export default function OrgChart() {
  return (
    <div className="w-full h-full min-h-[700px] flex items-center justify-center bg-[#0a0a0a] rounded-xl relative overflow-hidden py-12 px-6">
      {/* Deep Space Background Canvas */}
      <div className="absolute inset-0 bg-[radial-gradient(ellipse_80%_80%_at_50%_-20%,rgba(94,106,210,0.1),transparent)]"></div>
      <div className="absolute inset-0 bg-[radial-gradient(rgba(255,255,255,0.04)_1px,transparent_0)] bg-[size:16px_16px]"></div>

      <FlowDiagram
        nodes={[
          {
            id: "ceo",
            content: (
              <ProfileNode icon={User} jobTitle="CEO" name="Torvalds" level="c-suite" active />
            ),
          },
          {
            id: "cto",
            content: <ProfileNode icon={Cpu} jobTitle="CTO" name="Turing" level="vp" active />,
          },
          {
            id: "cpo",
            content: <ProfileNode icon={Briefcase} jobTitle="CPO" name="Jobs" level="vp" />,
          },
          {
            id: "fe",
            content: (
              <ProfileNode icon={Code} jobTitle="Frontend Lead" name="Hopper" level="lead" active />
            ),
          },
          {
            id: "be",
            content: (
              <ProfileNode icon={Database} jobTitle="Backend Lead" name="Hamilton" level="lead" />
            ),
          },
          {
            id: "design",
            content: (
              <ProfileNode
                icon={Paintbrush}
                jobTitle="Design Lead"
                name="Ive"
                level="lead"
                active
              />
            ),
          },
          {
            id: "security",
            content: (
              <ProfileNode
                icon={ShieldCheck}
                jobTitle="Security Lead"
                name="Schneier"
                level="lead"
              />
            ),
          },
        ]}
        relations={["ceo->cto", "ceo->cpo", "cto->fe", "cto->be", "cto->security", "cpo->design"]}
        direction="vertical"
        centered
        density="spacious"
      />
    </div>
  );
}
